// enumerate half → unordered_map<ll,ll> cntOfSum
// other half: for each sum s2 add cntOfSum[target - s2]
// complexity Θ(2^{n/2}) time/space vs impossible Θ(2^n)

// G(n) = 0·G(n-1) ++ 1·reverse(G(n-1))
vector<int> gray(int n){
    if (n == 0) return {0};
    vector<int> prev = gray(n - 1), out;
    for (int x : prev) out.push_back(x);            // first half: leading 0
    for (int i = prev.size() - 1; i >= 0; i--)
        out.push_back(prev[i] | (1 << (n - 1)));    // mirrored: leading 1
    return out;
}
// closed form: g(i) = i ^ (i >> 1)

void hanoi(int n, char src, char help, char dst){
    if (n == 0) return;
    hanoi(n - 1, src, dst, help);      // park n-1 aside
    cout << "move " << n << ' ' << src << "->" << dst << '\n';
    hanoi(n - 1, help, src, dst);      // bring them over
}
